{"command":"$desktop = [Environment]::GetFolderPath('Desktop')
$zip = Join-Path $desktop 'cc0_breaking_falling_hit_sfx.zip'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$archive = [System.IO.Compression.ZipFile]::OpenRead($zip)
try {
  $map = @{
    'bfh1_glass_breaking_01.ogg' = 'apex_like_armor_break_cc0_glass_breaking.ogg'
    'bfh1_metal_hit_02.ogg' = 'apex_like_armor_hit_cc0_metal_hit.ogg'
    'bfh1_hit_01.ogg' = 'apex_like_knockdown_cc0_hit.ogg'
  }
  foreach ($name in $map.Keys) {
    $entry = $archive.Entries | Where-Object { $_.FullName -eq $name } | Select-Object -First 1
    if ($entry) {
      $out = Join-Path $desktop $map[$name]
      [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $out, $true)
    }
  }
}
finally { $archive.Dispose() }
Get-ChildItem -LiteralPath $desktop | Where-Object { $_.Name -like 'apex_like_*' -or $_.Name -eq 'cc0_breaking_falling_hit_sfx.zip' } | Sort-Object Name | Select-Object Name,Length","timeout_ms":20000,"workdir":"C:\WeGameApps\rail_apps\OasisEraEditor(2001776)\ShadowTrackerExtra\UGCProjects\HunHuan"}
